css:
:root {
  --dryer-title: #0E5B67;
  --dryer-subtitle: #728DA5;

  --dryer-line: #4B7DA6;
  --dryer-arrow: #176A95;

  --dryer-stage-border: #4B83A7;
  --dryer-stage-number: #1C5A6B;
  --dryer-stage-label: #246975;

  --dryer-endpoint-text: #306897;
  --dryer-separator: #C8DAE5;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  border: none;
  background: transparent !important;
}

.dryer-header-widget {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  pointer-events: none;
}

.dryer-header-svg {
  display: block;
  width: 100%;
  height: 100%;

  background: transparent;
  font-family: Arial, Helvetica, sans-serif;
  shape-rendering: geometricPrecision;
}

/* Encabezado */
.dryer-title {
  fill: var(--dryer-title);
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0;
}

.dryer-subtitle {
  fill: var(--dryer-subtitle);
  font-size: 21px;
  font-weight: 400;
  letter-spacing: 0;
}

/* Entrada y salida */
.dryer-endpoint {
  fill: url("#dryer-endpoint-fill");
  stroke: none;
}

.dryer-endpoint-text {
  fill: var(--dryer-endpoint-text);
  font-size: 15px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
}

/* Recorrido horizontal */
.dryer-flow-line {
  fill: none;
  stroke: var(--dryer-line);
  stroke-width: 2.5;
  stroke-linecap: round;
}

.dryer-flow-arrows {
  fill: var(--dryer-arrow);
  stroke: none;
}

/* Identificadores circulares */
.dryer-stage-circle {
  fill: url("#dryer-stage-fill");
  stroke: var(--dryer-stage-border);
  stroke-width: 2.2;
}

.dryer-stage-number {
  fill: var(--dryer-stage-number);
  font-size: 23px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  text-anchor: middle;
  dominant-baseline: central;
}

.dryer-stage-label {
  fill: var(--dryer-stage-label);
  font-size: 20px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
}

/* Separadores discretos */
.dryer-separators {
  fill: none;
  stroke: var(--dryer-separator);
  stroke-width: 1.2;
  stroke-dasharray: 3 4;
}

