"use strict";

(function () {
  const DEFAULT_TITLE = "LÍNEA 2 / SECADOR";

  let titleElement = null;
  let svg = null;
  let latestWidget = null;

  function render(w) {
    if (!titleElement || !svg) return;

    const name =
      w && typeof w.name === "string"
        ? w.name.trim()
        : "";

    const title = name || DEFAULT_TITLE;

    // Muestra exactamente el Nombre del inspector.
    titleElement.textContent = title;

    svg.setAttribute(
      "aria-label",
      title +
      ". Vista general de los subprocesos. " +
      "Desde lavadora, 01 Zonas 1 y 2, " +
      "02 Zona 3, 03 Zonas 4 y 5, hacia rizado."
    );
  }

  /*
   * Actualiza el título al cambiar el Nombre del widget.
   * No utiliza variables del PLC.
   */
  window.onWidgetUpdate = function (w) {
    latestWidget = w;
    render(w);
  };

  function initialize() {
    titleElement = document.querySelector(".dryer-title");
    svg = document.querySelector(".dryer-header-svg");

    if (!titleElement || !svg) return;

    render(latestWidget || window.WIDGET || null);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
